	TITLE 'Special Slabs'****************************************************************** SpecialRect  (RectPtr,FrameColor,FillColor)** This is special purpose code to Erase	and Frame a given* rectangle.** The background is	turned to $FFFF and	the foreground is* turned to $0000.	The frame size is 1x1 in 320 mode and* 2x1 in 640 (the 2	is width).** By erasing and framing in 1 call rather than in 2, we do less* setup and call seek region far fewer times.***	 Copyright (C) 1986-1989*	 Apple Computer, Inc.*	 All Rights Reserved*** Change History** 06 Jan 88	Steven Glass** Coding Begins** 31 March 88	Steven Glass** The setup code did not check the special case where FinishWord* was zero.  In this case, AlmostFinishWord was set to $FFFE* instead of zero.  A special check was added just before the* value was decremented.** 19 April 88	Harry Yee and Dan Oliver** Put check at beginning of SpecialRect call to check if QDAux is * loaded but never started up. (We check if WAP is zero or not)** The busy flag was incremented from QDStart and never decremented. * The busy flag is now decremented upon exit from SpecialRect.** 17 May 88	Steven Glass** DrawBlack and DrawWhite were rewritten.  DrawBlack did not use* the frame color and always drew in black.  Both routines were* rewritten to copy through masks more quickly (thanks to owen rubin* for suggestion).** Removed call to decrement busy flag from code (added 19 April)* Real bug was in Endcall routine in file QDAux.  This too* was fixed today.** 01 Jun 88	Steven Glass** Adjustments made to setup to handle case were rect is clipped* in 640 mode in the middle of the 2-pixel wide frame.** Another adjustment was made to the code that combined the* left and right words when the rect drawn fits in less than 5* words.** 2/27/89	Konstantin** Special case to not call seek region when the rectangle is wholly* contained.*  ****************************************************************	include 'all.macros'	include 'special.macros'	include '::qd:qdequates:core.globals1'	include '::qd:qdequates:core.globals2'	include '::qd:qdequates:region.equs'	include '::qd:qdequates:rect.equs'	include '::qd:qdequates:slab.equs'	include '::qd:qdequates:line.equs'	include '::qd:qdequates:qd.data.asm'LeftWords	equ RgnHandleCRightWords	equ RgnPtrCAlmostFinishWord	equ PatTheFrameColor	equ DrawMaskTheFillColor	equ DrawMask+2DecBusyFlg	equ $E10068	IMPORT QDStart	Import BusyEC8	Entry DrawWhite	Entry DrawBlack	eject*****************************************************************SpecialRect	Proc Export** Fast routine to fill and frame a rect.  The frame is 1x1 in* in 320 mode and 1x2 in 640 mode.  This is faster than* the separate calls of filling and framing because we* seek region only once instead of 5 times.*** Inputs:*	Ptr to Rect* 	Frame Color Word*	Fill Color Word** Outputs:*	none** External Refs:	import DrawWhite	import DrawBlack** Entry Points:*	none*	longa on	; mode	longi on*****************************************************************	DefineStackOrigD	wordRTL1	block 3RTL2	block 3FillColor	wordFrameColor	wordRectPtr	LONG	tax	; just in case QDAux is loaded but	bne ok	; never started up	tyx	bne ok	lda #1	; tool not found	sec	rtl ok	jsr QDStart	; activate qd;=================================================;; Put copy of the desired rectangle in both; Rect1 and Rect2.;	lda RectPtr,s	sta Temp	lda RectPtr+2,s	sta Temp+2	ldy #6 @1	tyx	lda [Temp],y	sta Y1,x	sta Rect2,x	dey	dey	bpl @1;==================================================;; Put the frame and fill colors on direct page.;	    	lda FillColor,s	sta TheFillColor	lda FrameColor,s	sta TheFrameColor;==================================================;; Do the standard setup and clipping.;	    	jsl PortLoc2ZP	jsl SetUpPortRegions	jsl BMakeMinRect	bcc continue	brl NeverMindcontinue	lda MinRect	; copy clipped rect back to rect 1.	sta Y1	lda MinRect+2	sta X1	lda MinRect+4	sta Y2	lda MinRect+6	sta X2	jsl ShieldCursor	phb	jsl Init2Regions;=================================================;; Do the equivalent	to XSetup.  This includes;;   StartWord	          (offset on scanline for first word that changes);   LeftMask	          (mask for first word that changes to protect pixels outside rect);   LeftWords & LeftWords+2   (The first and second word on scan line.  These are setup;	           as 0's and F's.  The 0's represent frame color (or parts;	           to be masked off) and the F's represent fill color.  The real;	           color is applied later.;   FinishWord	          (Last word on scan line to change);   RightMask	          (Mask for last word on scan line to change.);   RightWords & RightWords+2 (The second to last and last words on scan line.  These are setup;	           as 0's and F's.  The 0's represent frame color (or parts;	           to be masked off) and the F's represent fill color.  The real;	           color is applied later.;   AlmostFinishWord          (Two less than finish word or StartWord, which ever is bigger);; In Setting up LeftWords and RightWords we have to check for the case where; the rectangle is clipped.  We do not want the frame to appear around the clipped; rectangle.;	bit PortSCB-1	bmi ModeIs640	brl ModeIs320ModeIs640	lda X1	; convert local coordinates to 	sec	; memory coordinates	sbc BoundsRect+2	; starting with left point	tay	; put copy in y	and #$0007	; use last 7 bits to get values out of	asl a	; tables	tax	tya	; retrieve y	lsr a	; turn into byte and	lsr a	and #$FFFE	; make even	sta StartWord	lda >LeftMaskTable,x ; setup leftmask and left edge of drawing	sta LeftMask	lda X1	; see if the left edge was clipped	cmp Rect2+2	; Compare to original rect	beq NoClipLeft640	; its same so no clipping	dec a	; Not same so some clipping occured.	cmp Rect2+2	; if it is off by one edge is split!	beq SplitClipLeft	lda #$FFFF	; left edge does not show at all so make words	tay	; all fill color.	bra StoreLeft640SplitClipLeft	lda >LeftMaskTable+2,x	tay	lda #$FFFF	bra StoreLeft640NoClipLeft640	lda >LeftEdgeTable,x	tay	lda >LeftEdgeTable2,xStoreLeft640	sty LeftWords	sta LeftWords+2	lda X2	; convert local coordinates to memory	sec	; coordinates for right edge	sbc BoundsRect+2	dec a	; dec by 1 for qd's rep of rectangles	tay	; save in y for now	and #$0007	asl a	tax	tya	lsr a	lsr a	and #$FFFE	sta FinishWord	lda >RightMaskTable,x	sta RightMask	lda X2	; check to see if right edge was clipped	cmp Rect2+6	beq NoClipRight640	; no, not at all	inc a	; it was clipped, is it split or completely obliterated.	cmp Rect2+6	beq SplitClipRight	; egads, its split.	lda #$FFFF	tay	bra StoreRight640SplitClipRight	lda >RightMaskTable-2,x	tay	lda #$FFFF	bra StoreRight640NoClipRight640	lda >RightEdgeTable,x	tay	lda >RightEdgeTable2,xStoreRight640	sta RightWords	sty RightWords+2	bra FinishSetupModeIs320	lda X1	; convert local coordinates to 	sec	; memory coordinates	sbc BoundsRect+2	; starting with left point	tay	; put copy in y	and #$0003	; use last 3 bits to get values out of	asl a	; tables	asl a	tax	tya	; retrieve y	lsr a	; turn into byte and	and #$FFFE	; make even	sta StartWord	lda >LeftMaskTable,x ; setup leftmask and left edge of drawing	sta LeftMask	lda X1	cmp Rect2+2	beq NoClipLeft320	lda #$FFFF	tay	bra StoreLeft320NoClipLeft320	lda >LeftEdgeTable,x	tay	lda >LeftEdgeTable2,xStoreLeft320	sty LeftWords	sta LeftWords+2	lda X2	; convert local coordinates to memory	sec	; coordinates for right edge	sbc BoundsRect+2	dec a	; dec by 1 for qd's rep of rectangles	tay	; save in y for now	and #$0003	asl a	asl a	tax	tya	lsr a	and #$FFFE	sta FinishWord	lda >RightMaskTable+2,x	sta RightMask	lda X2	cmp Rect2+6	beq NoClipRight320	lda #$FFFF	tay	bra StoreRight320NoClipRight320	lda >RightEdgeTable+2,x	tay	lda >RightEdgeTable2+2,xStoreRight320	sta RightWords	sty RightWords+2;-----------------------------------------------------------;; To finish up our setup we calculate AlmostFinishWord and ; then make any adjustments that are necessary for scan; lines less than 5 words long.;FinishSetup	lda FinishWord	; init AlmostFinishWord to FinishWord-2	beq @1	; (if this is zero, so is almost finish word)	dec a	; or startword, whichever is bigger	dec a	cmp StartWord	bcs @1	lda StartWord@1	sta AlmostFinishWord	lda StartWord	; check the degenerate case where start	and	cmp FinishWord	; stop are the same	bne LastCheck	lda RightMask	; merge left and right mask (only left will	and LeftMask	; be used)	sta LeftMask	lda LeftWords	; merge left and right edges (only left	will	and RightWords+2	; be used)	sta LeftWords	bra SetupDoneLastCheck	lda FinishWord	; as long as there are 4 or more words to 	sec	; do, then we will use LeftWord, LeftWord+2	sbc StartWord	; RightWord and RightWord+2	cmp #6	bcs SetupDone	cmp #4	bne Not3Words; 3 words		; we will use LeftWord, RightWords and RightWord+2	lda LeftWords+2	; so we merge the middle words and put result into	and RightWords	; RightWords	sta RightWords	bra SetupDoneNot3Words; 2 words		; we will use LeftWord and RightWord+2	lda LeftWords	; 	and RightWords	sta LeftWords	lda LeftWords+2	and RightWords+2	sta RightWords+2;-----------------------------------------------------------;; The last real part of the setup is to apply the foreground; and background colors to the left and right words.;SetupDone	lda LeftWords	and TheFillColor	; apply color to 1's	pha	lda LeftWords	eor #$FFFF	and TheFrameColor	; apply color to 0's	ora 1,s	sta LeftWords	pla	lda LeftWords+2	and TheFillColor	; apply color to 1's	pha	lda LeftWords+2	eor #$FFFF	and TheFrameColor	; apply color to 0's	ora 1,s	sta LeftWords+2	pla	lda RightWords	and TheFillColor	; apply color to 1's	pha	lda RightWords	eor #$FFFF	and TheFrameColor	; apply color to 0's	ora 1,s	sta RightWords	pla	lda RightWords+2	and TheFillColor	; apply color to 1's	pha	lda RightWords+2	eor #$FFFF	and TheFrameColor	; apply color to 0's	ora 1,s	sta RightWords+2	pla;=================================================;=================================================;; Do whats in the SetFirstDestref subroutine.;		; jsr SetFirstDestref	lda Y1	sta CurrentY	sec	sbc BoundsRect	pha	pha	pha	pei Width	_Multiply	pla	clc	adc ImageRef	sta DestRef	pla	adc ImageRef+2	and #$00FF	sta DestRef+2	phb	; set data bank to bank containing this	scan line	lda DestREf+1	sta 0,s	plb;=================================================; Draw The Top Line	jsl Seek2Regions	lda Y1	cmp Rect2	bne NoBlackOnTop	jsl DrawBlack	bra TopDrawnNoBlackOnTop	inc a	cmp Y2	beq DrawOneLine	jsl DrawWhiteTopDrawn	lda CurrentY	inc a	sta CurrentY	inc a	cmp Y2	bmi DrawMiddle	beq DrawEnd	bra TheEndDrawMiddle;------------------------------------------------------------------;Check to see if we can draw fast.  We can if we are drawing to; a rectangular region.;	lda NonRectRegions	beq DrawFastMiddle;------------------------------------------------------------------DrawMiddleOld	jsr SetNextDestRef	jsl Seek2Regions	jsl DrawWhite	lda CurrentY	inc a	sta CurrentY	inc a	cmp Y2	bmi DrawMiddleOldDrawEnd	jsr SetNextDestRef	jsl Seek2RegionsDrawOneLine	lda Y2	cmp Rect2+4	bne NoBlackOnBottom	jsl DrawBlack	bra BottomDrawnNoBlackOnBottom	jsl DrawWhiteBottomDrawnTheEnd	plb	jsl UnshieldCursorNeverMind	jsl FreePortRegions	brl BusyEC8;------------------START OF FAST MIDDLE DRAW-------------------DrawFastMiddle	lda Y2	clc	;subtract (currentY+1)	sbc CurrentY	;line count	sta CurrentYDrawFast1	lda DestRef	clc	adc Width	sta DestRef	bcs DrawFast3DrawFast2	jsl DrawWhite	dec CurrentY	;line count	bne DrawFast1	jsr SetNextDestRef	bra DrawOneLineDrawFast3		inc DestRef+2	pei DestRef+1	plb	plb	bra DrawFast2;------------------END OF FAST MIDDLE DRAW-------------------;=================================================;; SetNextDestRef ;SetNextDestRef	lda DestRef	clc	adc Width	sta DestRef	bcs @1	rts@1	inc DestRef+2	phb	lda DestRef+1	sta 0,s	plb	rts;=================================================LeftMaskTable	dc.B %11111111,%11111111	dc.B %00111111,%11111111	dc.B %00001111,%11111111	dc.B %00000011,%11111111	dc.B %00000000,%11111111	dc.B %00000000,%00111111	dc.B %00000000,%00001111	dc.B %00000000,%00000011	dc.B %00000000,%00000000	; extra line for split frame clipping	dc.B %00000000,%00000000	; extra line for split frame clippingRightMaskTable	dc.B %11000000,%00000000	dc.B %11110000,%00000000	dc.B %11111100,%00000000	dc.B %11111111,%00000000	dc.B %11111111,%11000000	dc.B %11111111,%11110000	dc.B %11111111,%11111100	dc.B %11111111,%11111111;=================================================;; The Left and Right edge tables are supposed ; to provide the source pixels for the ; drawing routine at the left and right	edge; of the rectangle.;; In two cases they	do not work at all.;   1) when the left edge is supposed to;      start at pixel 7 of 640 mode, the ;      table cannot	set the first pixel;      of the second word to 0.;   2) when the right edge is supposed to end at;      pixel 0 of a	word, the table cannot set;      the last pixel of the prior word	to 0.LeftEdgeTable	dc.B %00001111,%11111111	dc.B %00000011,%11111111	dc.B %00000000,%11111111	dc.B %00000000,%00111111	dc.B %00000000,%00001111	dc.B %00000000,%00000011	dc.B %00000000,%00000000	dc.B %00000000,%00000000LeftEdgeTable2	dc.B %11111111,%11111111	dc.B %11111111,%11111111	dc.B %11111111,%11111111	dc.B %11111111,%11111111	dc.B %11111111,%11111111	dc.B %11111111,%11111111	dc.B %11111111,%11111111	dc.B %00111111,%11111111RightEdgeTable	dc.B %00000000,%00000000	dc.B %00000000,%00000000	dc.B %11000000,%00000000	dc.B %11110000,%00000000	dc.B %11111100,%00000000	dc.B %11111111,%00000000	dc.B %11111111,%11000000	dc.B %11111111,%11110000RightEdgeTable2	dc.B %11111111,%11111100	dc.B %11111111,%11111111	dc.B %11111111,%11111111	dc.B %11111111,%11111111	dc.B %11111111,%11111111	dc.B %11111111,%11111111	dc.B %11111111,%11111111	dc.B %11111111,%11111111	ENDP	eject************************************************************************ Drawing algorithm** Inputs:** StartWord* FinishWord* LeftWords* RightWords** Almost FinishWord*** In the case where	5 words or more are	drawn it works like	this**   Draw 1st word*   Draw 2nd word*   Draw Middle words*   Draw Last-1 word*   Draw Last word** Unfortunately, we	don't always get to draw that many so it * really works like	this**       Draw 1st word*       Bump Y*       if Y >= AlmostFinishWord goto Last2Words*       Draw 2nd word*       Bump Y*       if Y >= AlmostFinishWord goto Last2Words*       DrawMiddle Words** Last2Words*       if Y > AlmostFinishWord goto LastWord*       Draw Last-1	Word*       BumpY* LastWord*       if Y > FinishWord goto done*       DrawLastWord* Done* **********************************************************************	eject;=================================================;; DrawWhite;;; Change History;;; 31 March 88	Steven Glass;; Bug in code that drew middle words when clipping.; instead of comparing to almostFinishWord, we were; using FinishWord.  This made us go to far.;; 17 May 88	Steven Glass;; Re-wrote code that saved to dest through masks; to use method described by Owen Rubin as "Phred" test.; This does not burn hole and or in value but uses; 2 EORs with mask to protect and modify bits in dest.;DrawWhite	PROC	lda NonRectRegions	bne MustClipNoClip; word 1	ldy StartWord	lda LeftWords	eor (DestRef),y	and LeftMask	eor (DestRef),y	sta (DestRef),y; Word 2	iny	; bump y reg	iny	cpy AlmostFinishWord ; is this one or two word case	bcs @101	; may be done	lda LeftWords+2	sta (DestRef),y	iny	iny	cpy AlmostFinishWord	bcs @101; Middle Words	        	lda TheFillColor	; now we do the non-edge case@100	sta (DestRef),y	; store into dest	iny	; keep bumping till	done	iny	cpy AlmostFinishWord	bcc @100@101	bne @102	; if we get here and y is not equal to 		; the almost finish	word, then we have one		; of the cases where there is less than	4		; words to draw and	Last-1 Word must		; be skipped.; Last-1 Word	lda RightWords	sta (DestRef),y	iny	iny@102	cpy FinishWord	; now we check if LastWord needs to be done	bne @103; Last Word	lda RightWords+2	eor (DestRef),y	and RightMask	eor (DestRef),y	sta (DestRef),y@103	rtlMustClip; word 1	ldy StartWord	; get offset to starting word in y	lda LeftWords	eor (DestRef),y	and LeftMask	and [ScanMaskRef],y	eor (DestRef),y	sta (DestRef),y	iny	; bump y reg	iny	cpy AlmostFinishWord ; is this one or two word case	bcs @101	; may be done; word 2	lda LeftWords+2	eor (DestRef),y	and [ScanMaskRef],y	eor (DestRef),y	sta (DestRef),y	iny	iny	cpy AlmostFinishWord	bcs @101; middle words@100	lda TheFillColor	eor (DestRef),y	and [ScanMaskRef],y	eor (DestRef),y	sta (DestRef),y	iny	; keep bumping till	done	iny	cpy AlmostFinishWord	bcc @100@101	bne @102	; if we get here and y is not equal to 		; the almost finish	word, then we have one		; of the cases where there is less than	4		; words to draw and	Last-1 Word must		; be skipped.; LastWord -1	lda RightWords	eor (DestRef),y	and [ScanMaskRef],y	eor (DestRef),y	sta (DestRef),y	iny	iny@102	cpy FinishWord	; now check to see if last word needs to be done	bne @103; LastWord	lda RightWords+2	eor (DestRef),y	and RightMask	and [ScanMaskRef],y	eor (DestRef),y	sta (DestRef),y@103	rtl	ENDP	eject;=================================================;; DrawBlack;; Change History;; 16 May 88	Steven Glass;; Was not using the frame color when drawing this line.;; Also re-wrote code that saved to dest through masks; to use method described by Owen Rubin as "Phred" test.; This does not burn hole and or in value but uses; 2 EORs with mask to protect and modify bits in dest.;DrawBlack	PROC	lda NonRectRegions	bne MustClip	ldy StartWord	lda TheFrameColor	; get the frame color	eor (DestRef),y	; eor in the dest	and LeftMask	; mask off bits	eor (DestRef),y	; or bits masked off back in and restore other bits to 	sta (DestRef),y	; desired value	iny	iny	cpy FinishWord	bcs @101	lda TheFrameColor@100	sta (DestRef),y	iny	iny	cpy FinishWord	bcc @100@101	bne @102	lda TheFrameColor	eor (DestRef),y	and RightMask	eor (DestRef),y	sta (DestRef),y@102	rtlMustClip	ldy StartWord	; init the index in y	lda TheFrameColor	eor (DestRef),y	and LeftMask		and [ScanMaskRef],y	eor (DestRef),y	; and with dest	sta (DestRef),y	iny	iny	cpy FinishWord	bcs @101@100		lda TheFrameColor	eor (DestRef),y	and [ScanMaskRef],y	eor (DestRef),y	sta (DestRef),y	iny	iny	cpy FinishWord	bcc @100@101	bne @102	lda TheFrameColor	eor (DestRef),y	and [ScanMaskRef],y	eor (DestRef),y	sta (DestRef),y@102	rtl	ENDP	END